// Homepage hero video (owner request 2026-11-17: hero as a video like Fashion Nova).
// Full native resolution encode (owner: first compressed version was not clear, 2026-11-17).
// The hero photo stays as the poster/fallback; this swaps in a muted autoplaying loop.
window.HERO_VIDEO = "data:video/mp4;base64,";
(function () {
  var img = document.getElementById("heroImg");
  if (!img) return;
  var v = document.createElement("video");
  v.src = window.HERO_VIDEO;
  v.muted = true;
  v.loop = true;
  v.autoplay = true;
  v.setAttribute("muted", "");
  v.setAttribute("playsinline", "");
  v.setAttribute("aria-hidden", "true");
  v.poster = img.src;
  v.className = "hero-video";
  img.parentNode.replaceChild(v, img);
  var p = v.play();
  if (p && p.catch) p.catch(function () {});
})();
